cd /home/user/RL_Study/report-gepa/runs/originals/kpop-generations && python - <<'EOF'
import json, pandas as pd, numpy as np
for f in json.load(open('facts.json')):
    print('='*60)
    print(f['id'], '|', f['claim'])
    ns={'pd':pd,'np':np}
    for k,p in f['tables'].items():
        ns[k]=pd.read_csv(p)
    print(eval(f['code'], ns))
EOF
